/**
 * `<style>` → node styles, so an imported design arrives with its DESIGN.
 *
 * `import-html.ts` gives a correctly structured, fully editable, completely
 * UNSTYLED document: it maps tags to primitives and inline `style=""` to node
 * styles, and lists `style` among the tags it skips. Every design generated by
 * an agent — and every hand-written template worth importing — puts its CSS in
 * one `<style>` block and hangs it off class names, so ~4KB of styling per page
 * was being dropped on the floor. The class names were already retained on the
 * nodes; only the rules behind them were missing.
 *
 * ── Which selectors, and why only these ──────────────────────────────────────
 * Measured against 106 real templates rather than guessed. The selector
 * population is:
 *
 *     878  .a .b   descendant       853  .class          202  tag
 *     197  ::pseudo                 128  other (*, +)     95  .a.b
 *      80  @keyframes                25  :root            24  @media
 *      21  .a > b
 *
 * The four handled here — class, descendant, tag and `:root` — are ~78% of all
 * selectors and close to 100% of the ones that carry layout and colour. The
 * rest are deliberately NOT silently dropped: pseudo-elements, keyframes and
 * anything with a combinator this does not model are preserved verbatim as a
 * residual stylesheet on the page, so an import loses nothing visually even
 * where it cannot make something editable.
 *
 * ── Why not a real CSS engine ────────────────────────────────────────────────
 * A correct cascade needs the DOM, and this runs in a Worker with no DOM and a
 * hand-rolled tokenizer for exactly that reason. What it implements instead is
 * source order plus a crude specificity sort, which is what these stylesheets
 * actually rely on — they are single-author, single-file, and written flat.
 * Best-effort by design, like the HTML importer it extends.
 */

import { DAISY_COMPONENT_CLASSES } from "./daisy-components"
import type { Doc, Node } from "./schema"

export interface CssRule {
  /** Raw selector, one per rule (comma groups are split before this). */
  selector: string
  decls: Record<string, string>
  /** Breakpoint max-width in px, when the rule sat inside an @media. */
  maxWidth?: number
  /** Source order, for stable sorting. */
  order: number
}

export interface StylesheetParse {
  rules: CssRule[]
  /** `:root` custom properties — the design system's tokens. */
  rootVars: Record<string, string>
  /** Everything this module cannot model, kept verbatim rather than lost. */
  residual: string
}

const DECL_SPLIT = /;(?![^(]*\))/

function parseDecls(body: string): Record<string, string> {
  const out: Record<string, string> = {}
  for (const part of body.split(DECL_SPLIT)) {
    const i = part.indexOf(":")
    if (i < 0) continue
    const prop = part.slice(0, i).trim()
    const value = part.slice(i + 1).trim()
    if (prop && value) out[prop] = value
  }
  return out
}

/** Selectors this module can resolve against a node tree. */
function isModellable(sel: string): boolean {
  if (sel.startsWith("@") || sel.includes("::") || sel.includes(":")) return false
  if (/[>+~*[\]]/.test(sel)) return false
  return /^[.\w][\w.\s-]*$/.test(sel)
}

/**
 * Crude specificity: classes beat tags, more parts beat fewer. Enough to order
 * a single-author stylesheet correctly; not a substitute for the real algorithm.
 */
function specificity(sel: string): number {
  const parts = sel.trim().split(/\s+/)
  let score = 0
  for (const p of parts) score += (p.match(/\./g)?.length ?? 0) * 10 + (p.startsWith(".") ? 0 : 1)
  return score
}

export function parseStylesheet(css: string): StylesheetParse {
  const rules: CssRule[] = []
  const rootVars: Record<string, string> = {}
  const residual: string[] = []
  let order = 0

  // Strip comments first so a selector inside one cannot be matched.
  const clean = css.replace(/\/\*[\s\S]*?\*\//g, "")

  // Pull @media blocks out whole, record their contents against a breakpoint,
  // and leave the rest of the sheet to the flat pass below.
  const mediaRe = /@media([^{]+)\{((?:[^{}]*\{[^{}]*\}\s*)*)\}/g
  let m: RegExpExecArray | null
  const flat = clean.replace(mediaRe, (full, cond: string, body: string) => {
    const px = /max-width\s*:\s*(\d+)/.exec(cond)
    if (!px) {
      // min-width, print, prefers-* — not modelled, kept verbatim.
      residual.push(full)
      return ""
    }
    const maxWidth = Number(px[1])
    const inner = /([^{}]+)\{([^{}]*)\}/g
    let r: RegExpExecArray | null
    while ((r = inner.exec(body))) {
      for (const sel of r[1].split(",")) {
        const s = sel.trim()
        if (!s) continue
        if (isModellable(s)) {
          rules.push({ selector: s, decls: parseDecls(r[2]), maxWidth, order: order++ })
        } else {
          residual.push(`@media${cond}{${s}{${r[2]}}}`)
        }
      }
    }
    return ""
  })

  // @keyframes and any other at-rule: verbatim, never modelled.
  const atRe = /@(?:keyframes|supports|font-face|import)[^{]*\{(?:[^{}]*\{[^{}]*\}\s*)*\}|@import[^;]+;/g
  const flatNoAt = flat.replace(atRe, (full) => {
    residual.push(full)
    return ""
  })

  const ruleRe = /([^{}]+)\{([^{}]*)\}/g
  while ((m = ruleRe.exec(flatNoAt))) {
    const decls = parseDecls(m[2])
    for (const sel of m[1].split(",")) {
      const s = sel.trim()
      if (!s) continue
      if (s === ":root" || s === "html:root") {
        // Custom properties are the design system; plain declarations here are
        // page defaults and belong on the root node, not the token set.
        for (const [k, v] of Object.entries(decls)) {
          if (k.startsWith("--")) rootVars[k] = v
        }
        const nonVars = Object.entries(decls).filter(([k]) => !k.startsWith("--"))
        if (nonVars.length) {
          rules.push({ selector: "body", decls: Object.fromEntries(nonVars), order: order++ })
        }
        continue
      }
      if (isModellable(s)) {
        rules.push({ selector: s, decls, order: order++ })
      } else {
        residual.push(`${s}{${m[2]}}`)
      }
    }
  }

  return { rules, rootVars, residual: residual.join("\n") }
}

/** A node's own classes, as a set. */
function classSet(node: Node): Set<string> {
  return new Set((node.classes ?? "").split(/\s+/).filter(Boolean))
}

/**
 * Does `selector` match this node, given its ancestors?
 *
 * Descendant matching walks the ancestor chain right-to-left, which is how a
 * browser does it and is the only part of the cascade worth reproducing here.
 */
function matches(
  selector: string,
  nodeId: string,
  doc: Doc,
  parents: Map<string, string>,
  tags: Record<string, string>
): boolean {
  const parts = selector.trim().split(/\s+/).reverse()
  let currentId: string | undefined = nodeId

  for (let i = 0; i < parts.length; i++) {
    const part = parts[i]!
    let found = false
    while (currentId) {
      const node = doc.nodes[currentId]
      if (!node) break
      const ok = part.startsWith(".")
        ? part
            .split(".")
            .filter(Boolean)
            .every((c) => classSet(node).has(c))
        : tags[currentId] === part
      if (ok) {
        found = true
        // The leftmost part must match this exact node; ancestors may be any
        // distance above, so only the first step is anchored.
        currentId = parents.get(currentId)
        break
      }
      if (i === 0) return false // the subject itself must match
      currentId = parents.get(currentId)
    }
    if (!found) return false
  }
  return true
}

export interface ApplyResult {
  /** Nodes that gained at least one declaration. */
  styledNodes: number
  /** Declarations written across the document. */
  declarations: number
  /** Tokens lifted out of `:root`. */
  tokens: number
  /** CSS kept verbatim because it could not be modelled. */
  residual: string
  /** `var()` references retargeted onto the theme's own names. */
  retargeted: number
  /** Nodes given back a style the browser would have supplied. */
  uaRestored: number
  /** Class names dropped from nodes because this sheet defined them. */
  classesDropped: number
}

/**
 * Point every `var(--x)` at the name the THEME will actually emit.
 *
 * `:root{--rust:#c1512f}` is lifted into `theme.colors.rust` just above, and
 * `themeToCss` writes that out as `--color-rust`. The declarations this module
 * just copied onto the nodes still said `var(--rust)` — one prefix apart — so
 * every colour, max-width and radius token in an imported page resolved to
 * nothing. Measured over 200 real landing pages: 2,748 references, on every
 * single page, silently voided. The markup rendered, so an audit called it
 * clean; what shipped was the design with its palette taken out.
 *
 * Retargeting rather than ALSO emitting `--rust` at the root, because the bare
 * names are a namespace we do not own: `--accent`, `--ink` and `--bg` are what
 * the legacy page packs style themselves with. This way nothing new is claimed
 * and the page follows the theme — change the colour in the builder and the
 * imported design changes with it, which is the whole point of lifting the
 * tokens in the first place.
 *
 * `tests/html-import.test.ts` asserts a rendered import declares every var it
 * references, so the two names cannot drift apart again.
 */
function retargetVars(doc: Doc, lifted: Set<string>): number {
  if (lifted.size === 0) return 0
  let count = 0
  // Keeps any fallback: `var(--rust, #000)` → `var(--color-rust, #000)`.
  const rewrite = (value: string): string =>
    value.replace(/var\(\s*--([a-zA-Z0-9_-]+)/g, (whole, name: string) => {
      if (!lifted.has(name)) return whole
      count++
      return `var(--color-${name}`
    })

  const bag = (style: Record<string, string> | undefined) => {
    if (!style) return
    for (const [prop, value] of Object.entries(style)) {
      if (typeof value === "string" && value.includes("var(--")) {
        style[prop] = rewrite(value)
      }
    }
  }

  for (const node of Object.values(doc.nodes)) {
    bag(node.style as Record<string, string> | undefined)
    for (const ov of Object.values(node.responsive ?? {})) {
      bag(ov.style as Record<string, string> | undefined)
    }
  }
  // A shared style rule keeps its declarations in `base`, and its breakpoint
  // overrides in `context` — not the `style`/`responsive` a NODE uses.
  for (const rule of Object.values(doc.styles ?? {})) {
    bag(rule.base)
    for (const ov of Object.values(rule.context ?? {})) bag(ov)
  }
  return count
}

/**
 * The styles the BROWSER would have given, where the sheet gave none.
 *
 * Our preflight normalises two groups of UA defaults away —
 * `:where(.bapp-root) :where(h1..h6,p,figure,blockquote,dl,dd,pre){margin:0}`
 * and `:where(button,input,optgroup,select,textarea){font:inherit}` — and a
 * page written against the browser's defaults never said so out loud. It is
 * the right preflight for a page authored HERE, where every design is written
 * against it, and the wrong one for a page that arrives already finished.
 *
 * Measured over 30 of the 200-page corpus with `scripts/check-import-boxes.mts`,
 * before this pass: 556 of 8,203 elements (6.8%) sat somewhere other than where
 * the source put them, and every one of the leading signatures was one of these
 * two losses — `figure y-16`, `blockquote y-15`, `p y-16` (the vertical UA
 * margin), and `button h+4`, `input h+4` (`font: inherit` handing a control the
 * body's `line-height` where the UA gives it `normal`), plus the containers
 * those sit in reporting the same difference one level up.
 *
 * ── Why these values ───────────────────────────────────────────────────────
 *
 * Read out of a current engine rather than recalled: `getComputedStyle` on a
 * bare document of one element per tag. The heading margins come back as a
 * ratio of the heading's OWN font-size (h1 21.44px at 32px, h2 19.92 at 24,
 * h3 18.72 at 18.72, h4 21.28 at 16, h5 22.1776 at 13.28, h6 24.9776 at
 * 10.72), so they are restored in `em` — which is also what makes restoring
 * them safe at a font-size the author changed: `0.67em` is what the UA would
 * have computed there too, not a 21px guess frozen from a 16px page.
 *
 * ── Why this is not "fighting the author" ──────────────────────────────────
 *
 * An earlier version of this restored only the horizontal margins on `figure`
 * and `blockquote`, on the reasoning that vertical margins are set
 * deliberately by essentially every real design. The first half is true and
 * the conclusion was wrong: a design that sets them is skipped by the guard
 * below, and the measurement says the remaining elements — the ones where the
 * author set NOTHING — are precisely where the loss showed. The guard is per
 * property group, so a `<p>` that sets `margin-bottom` keeps its own and gains
 * nothing, and a page carrying its own `*{margin:0}` reset is left alone
 * entirely (see `universalMarginReset`).
 */
const UA_MARGIN: Record<string, Record<string, string>> = {
  p: { "margin-top": "1em", "margin-bottom": "1em" },
  h1: { "margin-top": "0.67em", "margin-bottom": "0.67em" },
  h2: { "margin-top": "0.83em", "margin-bottom": "0.83em" },
  h3: { "margin-top": "1em", "margin-bottom": "1em" },
  h4: { "margin-top": "1.33em", "margin-bottom": "1.33em" },
  h5: { "margin-top": "1.67em", "margin-bottom": "1.67em" },
  h6: { "margin-top": "2.33em", "margin-bottom": "2.33em" },
  dl: { "margin-top": "1em", "margin-bottom": "1em" },
  pre: { "margin-top": "1em", "margin-bottom": "1em" },
  figure: {
    "margin-top": "1em",
    "margin-bottom": "1em",
    "margin-left": "40px",
    "margin-right": "40px",
  },
  blockquote: {
    "margin-top": "1em",
    "margin-bottom": "1em",
    "margin-left": "40px",
    "margin-right": "40px",
  },
  // The only one with a horizontal default and no vertical one.
  dd: { "margin-left": "40px" },
}

/**
 * Controls whose metrics `font: inherit` overwrites.
 *
 * Only `line-height` is restored, and only that because only that was measured
 * to be wrong: `button h+4` and `input h+4` were the two leading signatures in
 * the box comparison, and after this they leave the list entirely.
 *
 * The UA also gives a control its own `font-size` (13.333px) and `font-family`
 * (the system UI face, monospace for a `<textarea>`), and those are NOT
 * restored. Nothing in the corpus asked for it — a page that styles its
 * buttons sets the size itself, so the restore would almost always be skipped
 * by the guard anyway — and handing an unstyled button back 13.333px Arial on
 * a page whose body font is something else is a bigger change than the one it
 * would be correcting. If a real page ever turns up needing them, the
 * measurement is the thing to add them on, not this reasoning.
 */
const UA_FORM_TAGS = new Set(["button", "input", "select", "textarea"])

/**
 * What a `<table>` does before anyone styles it.
 *
 * Our preflight carries Tailwind's `table{border-collapse:collapse}`, and the
 * UA default is `separate` with `border-spacing: 2px`. Two pixels between
 * every pair of cells sounds like nothing and is not: on the comparison table
 * in `saas/callframe` it is 24 cells each between 3px and 8px out, because the
 * spacing accumulates across the row and the collapsed version redistributes
 * the width differently. Restored only when the author set neither property —
 * and most real tables do set `border-collapse`, which is why this is a
 * handful of pages rather than all of them.
 */
const UA_TABLE: Record<string, string> = {
  "border-collapse": "separate",
  "border-spacing": "2px",
}

/**
 * What else can speak for one margin, so the restore keeps quiet.
 *
 * Per PROPERTY, not per group. A `<figure class="mb-16">` has said something
 * about its bottom margin and nothing about its sides, and a group-wide guard
 * read that as "the author handles margins here" — which left five figures on
 * one page sitting 40px left and 80px wide of where the source drew them,
 * the single largest cluster left after the first pass of this restore.
 *
 * `style` lists the longhand itself plus every shorthand that would set it;
 * `utility` matches the class names the generator turns into the same thing.
 * A shorthand in the class list (`m-4`, `mx-auto`) therefore still silences
 * all four sides, because it genuinely does set all four.
 */
const MARGIN_GUARDS: Record<string, { style: string[]; utility: RegExp }> = {
  "margin-top": {
    style: ["margin", "margin-block", "margin-block-start"],
    utility: /(^|\s)-?m[ty]?-/,
  },
  "margin-bottom": {
    style: ["margin", "margin-block", "margin-block-end"],
    utility: /(^|\s)-?m[by]?-/,
  },
  "margin-left": {
    style: ["margin", "margin-inline", "margin-inline-start"],
    utility: /(^|\s)-?m[lsx]?-/,
  },
  "margin-right": {
    style: ["margin", "margin-inline", "margin-inline-end"],
    utility: /(^|\s)-?m[rex]?-/,
  },
}

/** `leading-6`, `leading-tight`, `leading-[1.2]`. */
const LEADING_UTILITY = /(^|\s)leading-/
/** For a property no utility class of ours sets. */
const NO_UTILITY = /(?!)/

/**
 * Did the author say anything that would set this property?
 *
 * Inline and class declarations have both landed on `node.style` by now, and a
 * utility class never will — the generator turns it into CSS at render time —
 * so the class list has to be read as well. A responsive override is
 * deliberately NOT consulted: a margin set only inside a media query leaves the
 * base unstated, and the base is what the UA would have supplied.
 */
function authorSet(
  node: Doc["nodes"][string],
  property: string,
  shorthands: string[],
  utility: RegExp
): boolean {
  const style = node.style ?? {}
  if (property in style) return true
  for (const key of shorthands) if (key in style) return true
  return utility.test(node.classes ?? "")
}

function restoreUaDefaults(
  doc: Doc,
  tags: Record<string, string>,
  universalMarginReset: boolean
): number {
  let count = 0
  for (const [id, node] of Object.entries(doc.nodes)) {
    const tag = tags[id] ?? ""
    const give: Record<string, string> = {}

    const margins = UA_MARGIN[tag]
    if (margins && !universalMarginReset) {
      for (const [property, value] of Object.entries(margins)) {
        const guard = MARGIN_GUARDS[property]!
        if (authorSet(node, property, guard.style, guard.utility)) continue
        give[property] = value
      }
    }

    if (
      UA_FORM_TAGS.has(tag) &&
      // `font: 14px/1.2 sans` sets the line-height too, so the shorthand counts.
      !authorSet(node, "line-height", ["font"], LEADING_UTILITY)
    ) {
      give["line-height"] = "normal"
    }

    if (tag === "table") {
      for (const [property, value] of Object.entries(UA_TABLE)) {
        // `border` is a shorthand for the EDGE, not for collapsing, so only
        // these two names and their utility classes can speak here.
        if (authorSet(node, property, [], NO_UTILITY)) continue
        if (property === "border-collapse" && /(^|\s)border-(collapse|separate)(\s|$)/.test(node.classes ?? "")) continue
        give[property] = value
      }
    }

    if (Object.keys(give).length === 0) continue
    node.style = { ...(node.style ?? {}), ...give }
    count++
  }
  return count
}

/**
 * Forget a class name that can only do harm now its rules are on the node.
 *
 * The importer keeps `class=""` because a source authored in Tailwind needs it
 * — the generator turns those tokens into CSS at render time. Two kinds of
 * name are dropped anyway.
 *
 * ── A name this sheet DEFINED ──────────────────────────────────────────────
 *
 * Its declarations have just been copied onto the node, so the bare name has
 * nothing left to contribute and can still collide. The utility generator also
 * answers to daisyUI's component names, so a hand-written `.hero` picked up
 * `display:grid; place-items:center`, and the generated CSS is concatenated
 * AFTER the node styles, so it won. Measured over the 200-page corpus: `.hero`
 * on all 200, plus `btn-ghost` (83), `stat-value` (44), `stats` (30), `stat`
 * (28), `stat-title` (25), `tab` and `tab-active` (21 each), `steps` (19) and
 * `badge` (12).
 *
 * ── A daisyUI COMPONENT name, defined here or not ──────────────────────────
 *
 * The rule above missed the case where the page never styled the name at all.
 * `education/mimico` has a plain `<section class="hero">` that its own
 * stylesheet says nothing about — so the name survived, the generator answered
 * it with the daisyUI hero component, and the band collapsed from a full-width
 * stage to a narrow centred box with the mascot sitting on top of the
 * headline and the call to action gone. Of the 265 distinct class names that
 * survived the import across those 200 pages, exactly two generated any CSS,
 * and `hero` was one of them.
 *
 * Only names Tailwind itself does not answer to are listed in
 * `DAISY_COMPONENT_CLASSES`, which is why this cannot cost a page a real
 * utility: `my-6` on a page that mixes its own `<style>` with Tailwind is not
 * in the list and stays.
 *
 * ── The one exception ──────────────────────────────────────────────────────
 *
 * A name the RESIDUAL still mentions is load-bearing: `.card:first-child`
 * could not be resolved onto a node, so it is emitted as a rule, and a rule
 * needs its class on the element to match. Correct residual beats a tidier
 * class list — on the 200-page corpus that holds back three names in total.
 */
function pruneClasses(doc: Doc, defined: Set<string>, spare: Set<string>): number {
  let touched = 0
  for (const node of Object.values(doc.nodes)) {
    if (!node.classes) continue
    const had = node.classes.split(/\s+/).filter(Boolean)
    const keep = had.filter(
      (c) => spare.has(c) || (!defined.has(c) && !DAISY_COMPONENT_CLASSES.has(c))
    )
    if (keep.length === had.length) continue
    node.classes = keep.join(" ") || undefined
    touched++
  }
  return touched
}

/**
 * Resolve a stylesheet onto a Doc, in place.
 *
 * Existing inline styles win: `style=""` in the source is more specific than
 * any class rule, and the HTML importer has already put those on the node.
 */
export function applyStylesheetToDoc(
  doc: Doc,
  css: string,
  tags: Record<string, string>,
  breakpointIdForWidth: (px: number) => string | undefined
): ApplyResult {
  const { rules, rootVars, residual } = parseStylesheet(css)

  const parents = new Map<string, string>()
  for (const [id, node] of Object.entries(doc.nodes)) {
    for (const childId of node.children ?? []) parents.set(childId, id)
  }

  const ordered = [...rules].sort(
    (a, b) => specificity(a.selector) - specificity(b.selector) || a.order - b.order
  )

  let styledNodes = 0
  let declarations = 0
  const touched = new Set<string>()

  for (const nodeId of Object.keys(doc.nodes)) {
    const node = doc.nodes[nodeId]!
    const inline = { ...(node.style ?? {}) }

    for (const rule of ordered) {
      if (!matches(rule.selector, nodeId, doc, parents, tags)) continue

      if (rule.maxWidth != null) {
        const bp = breakpointIdForWidth(rule.maxWidth)
        if (!bp) continue
        const responsive = { ...(node.responsive ?? {}) }
        const slot = { ...(responsive[bp] ?? {}) }
        slot.style = { ...(slot.style ?? {}), ...rule.decls }
        responsive[bp] = slot
        node.responsive = responsive
        declarations += Object.keys(rule.decls).length
        touched.add(nodeId)
        continue
      }

      node.style = { ...(node.style ?? {}), ...rule.decls }
      declarations += Object.keys(rule.decls).length
      touched.add(nodeId)
    }

    // Re-apply the source's inline style last — it outranks every class rule.
    if (Object.keys(inline).length) node.style = { ...(node.style ?? {}), ...inline }
  }
  styledNodes = touched.size

  // `:root` custom properties are the imported design system's tokens.
  const lifted = new Set<string>()
  if (Object.keys(rootVars).length) {
    const colors: Record<string, string> = { ...(doc.theme?.colors ?? {}) }
    for (const [name, value] of Object.entries(rootVars)) {
      const key = name.replace(/^--/, "")
      colors[key] = value
      lifted.add(key)
    }
    doc.theme = { ...doc.theme, colors } as Doc["theme"]
  }
  const retargeted = retargetVars(doc, lifted)

  /**
   * Every class name this sheet defined — collected from the selectors, not
   * from the nodes, so a name that matched nothing is still forgotten.
   */
  const defined = new Set<string>()
  for (const rule of rules) {
    for (const m of rule.selector.matchAll(/\.([a-zA-Z0-9_-]+)/g)) defined.add(m[1]!)
  }
  // …except the ones the residual still has to match on. A daisyUI component
  // name the residual needs is spared here too, for the same reason.
  const needed = new Set<string>()
  for (const m of residual.matchAll(/\.([a-zA-Z0-9_-]+)/g)) needed.add(m[1]!)
  for (const name of needed) defined.delete(name)
  /**
   * A page that zeroes margins with `*` has said something about every tag.
   *
   * `matches()` cannot resolve a universal selector onto a node — nothing has
   * the tag `*` — so `*{margin:0}` never reaches `node.style`, and without
   * this the restore would hand UA margins back to a page that deliberately
   * cleared them. The residual is scanned as well as the parsed rules, since
   * a universal rule this module cannot model is kept there verbatim.
   */
  const universalMarginReset =
    rules.some(
      (r) =>
        /(^|[\s,>+~])\*/.test(r.selector) &&
        Object.keys(r.decls).some((k) => k.startsWith("margin"))
    ) || /(^|[\s,>+~{])\*[^{]*\{[^}]*margin/.test(residual)

  // Restored BEFORE the classes are pruned: the margin guard reads the class
  // list as the author wrote it, and `my-6` is the author saying "my margin".
  const uaRestored = restoreUaDefaults(doc, tags, universalMarginReset)
  const classesDropped = pruneClasses(doc, defined, needed)

  return {
    styledNodes,
    declarations,
    tokens: Object.keys(rootVars).length,
    // Retargeted too: a `var()` in here is now pointing at the theme's name,
    // so the residual works the day something renders it.
    residual: residual.replace(/var\(\s*--([a-zA-Z0-9_-]+)/g, (whole, name: string) =>
      lifted.has(name) ? `var(--color-${name}` : whole
    ),
    retargeted,
    classesDropped,
    uaRestored,
  }
}

/**
 * Prefix every selector in a stylesheet so it cannot reach outside the page.
 *
 * The companion to `residual`: the rules this module cannot model are kept
 * verbatim, and until now nothing rendered them — `meta.residualCss` was
 * stored and read by no one, so a `:hover`, a `@keyframes` or a
 * `.card:first-child` override was silently lost. They cannot simply be
 * emitted as written, either: a published page is one component inside an app
 * shell, and an imported `*{box-sizing:inherit}` or `body{margin:0}` would
 * reach the whole document.
 *
 * So each selector is scoped. `*` becomes `<scope> *`; `:root`, `html` and
 * `body` become the scope itself, because in the source they WERE the page.
 * `@media` and `@supports` keep their condition and have their contents
 * scoped; `@keyframes`, `@font-face` and `@import` pass through untouched,
 * since their insides are not selectors.
 *
 * Brace-matched rather than regexed, so a nested at-rule stays whole. The
 * matcher counts braces without tracking strings, so a `}` inside a quoted
 * value (`content:"}"`) would still fool it — the same best-effort bargain the
 * rest of this module makes, and the residual it runs over is the handful of
 * rules the parser already declined to model.
 */
export function scopeCss(css: string, scope: string): string {
  const out: string[] = []
  let i = 0

  const body = (from: number): { text: string; end: number } => {
    let depth = 0
    for (let j = from; j < css.length; j++) {
      if (css[j] === "{") depth++
      else if (css[j] === "}") {
        depth--
        if (depth === 0) return { text: css.slice(from + 1, j), end: j + 1 }
      }
    }
    return { text: css.slice(from + 1), end: css.length }
  }

  const scopeSelector = (raw: string): string =>
    raw
      .split(",")
      .map((part) => {
        const sel = part.trim()
        if (!sel) return ""
        if (sel === "*") return `${scope} *`
        if (sel === ":root" || sel === "html" || sel === "body") return scope
        // A selector that already starts at the scope is left alone, so
        // scoping twice is a no-op.
        if (sel === scope || sel.startsWith(`${scope} `)) return sel
        return `${scope} ${sel}`
      })
      .filter(Boolean)
      .join(",")

  while (i < css.length) {
    // Anything up to the next `{` is a selector or an at-rule prelude.
    const brace = css.indexOf("{", i)
    if (brace < 0) break
    const prelude = css.slice(i, brace).trim()
    const { text, end } = body(brace)
    i = end

    if (prelude.startsWith("@")) {
      const name = /^@([a-zA-Z-]+)/.exec(prelude)?.[1]?.toLowerCase() ?? ""
      if (name === "media" || name === "supports" || name === "layer") {
        out.push(`${prelude}{${scopeCss(text, scope)}}`)
      } else {
        // @keyframes, @font-face, @page, @property — their bodies are not
        // selectors, so scoping them would corrupt the rule.
        out.push(`${prelude}{${text}}`)
      }
      continue
    }
    const sel = scopeSelector(prelude)
    if (sel) out.push(`${sel}{${text}}`)
  }

  return out.join("")
}
